"""Generate the linked R5 release from final manufacturing manifests."""
from common import *
from html import escape as esc
from collections import Counter

CSS='''*{box-sizing:border-box}body{margin:0;color:#203b38;background:#f2f5f2;font:16px/1.75 system-ui,"Microsoft YaHei",sans-serif}main{max-width:1180px;margin:auto;padding:30px}nav{display:flex;gap:18px;flex-wrap:wrap;border-bottom:1px solid #cddbd4;padding-bottom:15px}a{color:#14695b;text-underline-offset:3px}h1{font-size:34px;line-height:1.3;margin:30px 0 18px}h2{font-size:24px;margin:32px 0 14px}h3{font-size:18px}p{max-width:90ch}.eyebrow,small{color:#677c74}.box{background:#dcebe3;border-left:4px solid #438a70;padding:18px;margin:20px 0}.pending{background:#fff1d9;border-color:#b67b31}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(245px,1fr));gap:16px}.card,details{background:white;padding:20px;border-radius:7px}table{width:100%;border-collapse:collapse;background:white;font-size:14px}td,th{text-align:left;vertical-align:top;border:1px solid #d0ded5;padding:9px}th{background:#e5eee7}code,pre{font:13px/1.65 Consolas,monospace;overflow-wrap:anywhere}pre{background:#e6ece7;padding:15px;white-space:pre-wrap}img{width:100%;max-height:690px;object-fit:contain;background:#edf0ef}.hero{display:grid;grid-template-columns:1fr 1fr;gap:24px;align-items:center}.hero img{max-height:520px}.tag{background:#e6eee8;padding:2px 10px;border-radius:20px}.tablewrap{overflow:auto}li{margin:5px 0}.caption{color:#64786f;font-size:14px}@media(max-width:760px){main{padding:18px}.hero{grid-template-columns:1fr}h1{font-size:28px}}@media print{nav{display:none}main{padding:0}a{color:inherit}.card,table,figure{break-inside:avoid}}'''
NAV='<nav>'+''.join(f'<a href="{f}">{n}</a>' for f,n in [('START_HERE.html','入口'),('preview/index.html','三维检查'),('PRINTING.html','打印'),('HARDWARE.html','物料'),('ASSEMBLY.html','装配'),('SENSING.html','测角原理'),('WIRING.html','接线走线'),('CALIBRATION.html','校准'),('VERIFICATION.html','验证')])+'</nav>'
def page(file,title,body):
    (OUT/file).write_text(f'<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="icon" href="data:,"><title>O24E R5 · {title}</title><style>{CSS}</style><main>{NAV}<p class="eyebrow">POSEDOLL / O24E / R5 / 2026-10-30</p><h1>{title}</h1>{body}</main></html>',encoding='utf8')
def table(headers,rows):
    return '<div class="tablewrap"><table><thead><tr>'+''.join('<th>'+h+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(c)+'</td>' for c in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def link(path,label=None):return f'<a href="{path}">{esc(label or path)}</a>'

def run():
    kit=load(OUT/'kit.json');cs=load(OUT/'channels.json');steps=load(OUT/'assembly_guide/steps.json')['steps'];count=len(steps)
    tools=load(OUT/'tooling/R5_new_tools.json')['parts'];plates=load(OUT/'printing/plates.json')['plates'];routing=load(OUT/'harness/routing_plan.json');pins=load(OUT/'electronics/pinmap.json')['channels']
    replacement=[p for p in kit['structural_parts'] if p.get('reprint')]
    reuse=[p for p in kit['structural_parts'] if p['reuse_R4_byte_identical']];new=[p for p in kit['structural_parts'] if p['new_accessory']]
    reasons={'SHOULDER_PITCH':'增加RP板托固定座与圆角侧入口，保留原托具路径。','UPPER_ARM':'增加RU板托固定座和侧入口，避开肘最大屈曲。','FOREARM':'增加RF板托固定座和侧入口；WF板夹装在原叉耳外侧。','KEEP_E-P018':'恢复磁铁压片螺孔、锁母入口和垫片座，复用原磁铁盲座。','KEEP_E-P019':'一体增加WD板支架和后盖，避开原腕内层垫片装入路径。'}
    rt=table(['原编号','重打印','修改原因'],[[p['part_number'].replace('R5-',''),link(p['stl'],p['part_number'])+' ×1',reasons[p['name']]] for p in replacement])
    page('START_HERE.html','R4单臂升级为七轴测角R5',f'''<div class="hero"><div><span class="tag">肩关节到手掌 · 7 DOF</span><p>保留已实装通过的R4摩擦和防脱方案，增加完整磁铁、板托、固定件和接线。六路复用O22 MT6701，腕侧摆使用独立S1三轴传感板；腕部两个自由度各有实际测量通道。</p><div class="box"><b>重打P005、P007、P009、P010、P012，各1件。</b><br>其余6个R4主件继续用。另打印29个测角附件＋J003/J004两件工装，共新增打印36件；原J001/J002继续用。</div></div><img src="images/arm.png" alt="R5真实分件装配：绿色主体、金色测角附件"></div>
<div class="grid"><div class="card">{link('preview/index.html','检查七轴整臂')}<p>314个实际安装实体；切换姿态、双轴腕及走线参考。</p></div><div class="card">{link('assembly_guide/index.html',str(count)+'步安装动画')}<p>含腕部预装、外部送料、螺母暂留、磁铁捕获。</p></div><div class="card">{link('PRINTING.html','两盘升级打印工程')}<p>5件主件一盘；29件附件＋2件新工装一盘。</p></div><div class="card">{link('CALIBRATION.html','通电和实测校准')}<p>固件、采集器和空白测量模板；没有虚构校准值。</p></div></div>
<h2>重打印范围</h2>{rt}<p>直接复用：<b>P001、P002、P003、P004、P006、P008</b>。P011早已并入一体手掌P010，并非漏件。</p><p>{link('O24E_R5_sensing_arm.blend','Blender可检查整臂')} · {link('O24E_R5_sensing_arm.glb','GLB装配')} · {link('kit.json','逐件物料')} · {link('README.txt','离线说明')}</p><div class="box pending">R4摩擦与姿态保持已获你的实物确认。R5几何、装配路径、切片和软件检查见验证页；新增测角的实际精度、磁干扰、装线后保持力仍待本次实物验证。没有把R4实装结果等同于R5电子验收；不要求重测T6 H/W作为开工前提。</div>''')
    pt=table(['打印盘','件数','用途'],[[link(p['file'],p['id']+'.3mf'),len(p['items']),'新装整臂备用，已有R4跳过' if p['optional'] else '本次升级打印'] for p in plates])
    page('PRINTING.html','打印工程与复用清单',f'''<div class="box">已有R4：只打印R5_UPGRADE_MAIN_1和R5_SENSORS_1两盘，共36件，含2件临时工装。</div>{pt}<h2>替换5个主件</h2>{rt}<h2>原样复用6件</h2>{table(['编号','名称'],[[p['part_number'],esc(p['kit_label'])] for p in reuse])}<p>这6个STL与R4逐字节相同。替换主件继承R4打印旋转方向，避免无意改变原承力层向。</p><h2>新增附件与工具</h2>{table(['编号','名称','数量'],[[link(p['stl'],p['part_number']),esc(p.get('kit_label',p.get('label',''))),1] for p in new+tools])}
<h2>打印和清理</h2><ol><li>A1 mini、0.4 mm、PLA、0.12 mm层高、5层墙、100%填充、自动支撑、3 mm裙边。打开后核对实际机器和耗材，不缩放模型。</li><li>清理侧窗、M1.6/M2孔、六角窝和PCB滑入面；不要磨薄摩擦面、定位筋、W6L挡肩或止转六角。</li><li>磁铁盲座D6.24适配D6×2.5；PCB为指定12×10 mm小板。M2孔D2.2；先干装实物，必要时仅去毛刺。</li><li>J003工作面朝上，用底托承重。J004浅口只保持/起牙，最终锁紧用外径≤6.5 mm的4 mm薄壁套筒。</li><li>后盖D1.3穿线孔保持通畅。0.2 mm软绝缘片与PET衬条需要裁切，不用PLA代替。</li></ol><p>离线切片没有发送打印任务。{link('verification/slicing.json','切片检查')} · {link('verification/stl_export.json','封闭网格与复用哈希')}</p>''')
    sku=Counter(p['sku'] for p in kit['hardware'] if not p.get('baseline_name') and p['role']!='magnet');oldhw=Counter(p['sku'] for p in kit['hardware'] if p.get('baseline_name'))
    specs={'M1.6x4_CS_BRASS':'M1.6×4黄铜十字沉头，总长含头4，头径≤3.2、头高≤0.96','N1.6_BRASS':'M1.6黄铜普通螺母，对边3.2、厚1.3','M2x10_CS_BRASS':'M2×10黄铜十字沉头，总长含头10，头径≤3.8、头高≤1.2','N2_BRASS':'M2黄铜普通螺母，对边4、厚1.6；两颗对顶','W2_BRASS':'黄铜平垫D5×d2.2×0.5','M2x20_BRASS':'M2×20黄铜圆柱头内六角，杆长不含头','M2x8':'M2×8圆柱头内六角，杆长不含头','W2':'平垫D5×d2.2×0.5','NL2':'M2尼龙锁紧螺母，对边4、总厚3','M2x8_BRASS':'M2×8黄铜圆柱头内六角','M2x10_BRASS':'M2×10黄铜圆柱头内六角','W2_OD7_BRASS':'黄铜大平垫D7×d2.2×0.5，WD防脱压片','NL2_BRASS':'M2黄铜尼龙锁紧螺母，对边4、总厚3'}
    extras=[['O22 MT6701CT小板',6,'优先拆用O22，12×10×1 mm，芯片中心在板中心。'],['S1 TMAG5170A1小板',1,'继承O24D/E S1，12×10×0.8 mm；随包KiCad制造参考。大尺寸开发板不能直接装。'],['O22 D6×2.5径向两极磁铁',7,'优先复用；不可换成轴向充磁。未知牌号以实际场强与标定验收。'],['O22载板＋XIAO ESP32S3',1,'复用现有方案；刷R5固件、增加专用WD线。'],['10 kΩ电阻＋GPIO3跳线',1,'WD独立片选，上拉至MCU 3V3。'],['5芯/6芯柔线','6束/1束','32 AWG多股、单线外径≤0.65 mm；长度见走线页。'],['0.20 mm软绝缘缓冲片',7,'每片11.6×8 mm，PCB无元件背面，可微压缩。'],['0.10 mm PET夹座衬条',3,'每条2.5×约50 mm，只贴夹座接触带，避开FW4。'],['软绑线、热缩管、低粘胶带','少量','应力释放、绝缘、外侧暂留。'],['可剥离中性胶、兼容塑料的低强度金属螺纹锁固剂','少量','磁铁/六角止转消隙，M1.6螺纹防松；机械防脱不依赖胶。']]
    extras.append(['JST SH 1.00 mm 5P配套线端/预压接尾线',7,'复用O22匹配BM05B-SRSS-TB的线端；6个用于MT，1个是WD专用转接。WD另加GPIO3单线，颜色与针序逐线测通断。'])
    put(OUT/'materials_manifest.json',dict(replacement_main=[p['part_number'] for p in replacement],reused_main=[p['part_number'] for p in reuse],new_accessories=[p['part_number'] for p in new],tools=tools,new_metal_quantities=dict(sku),reused_R4_metal_quantities=dict(oldhw),electronics_and_consumables=extras,inventory_on_hand='UNKNOWN',custom_metal_machining=False))
    page('HARDWARE.html','五金、电子件与补齐清单',f'''<p>R4的<b>136件机械五金全部复用</b>；新增117件常见小五金、7颗磁铁和7块板。没有车铣件、切短轴、切短螺钉。库存余量未知；按装配所需数量核对O22/R4余件后补差额。</p><h2>新增五金</h2>{table(['代号','数量','实物配合条件'],[[esc(k),v,specs[k]] for k,v in sorted(sku.items())])}<p>靠近磁铁的新增件采用黄铜，降低磁场畸变；不要直接换成强磁钢件。原R4钢肩钉保留，整套五金装齐后标定。小型黄铜尼龙锁母核对对边和厚度，超尺寸不能硬压壳体。</p><h2>电子件与软材料</h2>{table(['物料','数量','复用/安装说明'],extras)}<h2>原R4五金</h2>{table(['代号','数量'],sorted(oldhw.items()))}<p>压盖仍用M3普通双螺母；运动预紧处的NL3、A8、FW4保留，不把所有NL3替成普通螺母。</p><h2>工具</h2><p>原J001/J002，新J003/J004；1.5/2/2.5 mm内六角、微型十字起子、4 mm薄壁套筒（外径≤6.5 mm）、原R4螺母扳手、卡尺、软爪台钳、焊接/万用表工具、用于标定的可靠机械角度尺。</p><p>{link('kit.json','逐件编号与物料')} · {link('materials_manifest.json','汇总数量')}</p>''')
    names={'RP':'肩前举/后伸','HS':'肩外展','RU':'上臂旋转','HE':'肘屈伸','RF':'前臂旋转','WF':'腕屈伸','WD':'腕侧摆'}
    rows=[]
    for c in sorted(cs,key=lambda c:list(names).index(c['id'])):
        lim=next(a['limits_deg'] for a in PROFILE['axes'] if a['id']==c['axis']);rows.append([c['id']+' '+names[c['id']],str(lim),'S1 TMAG5170A1 XYZ' if c['id']=='WD' else 'O22 MT6701 SSI',esc(c['pcb_frame']),esc(c['magnet_frame'])])
    page('SENSING.html','七个关节如何测角',f'''<p>六路同轴MT6701＋一路独立腕侧摆磁场测量。板和磁铁固定在关节两侧，读取相对运动；没有用一个磁铁反解整个球面腕。</p>{table(['关节','范围°','传感器','板固定坐标系','磁铁固定坐标系'],rows)}
<h2>六路同轴MT</h2><p>磁铁座六角插入已锁固的AX4肩钉头；盲座、盖口、两颗M1.6沉头螺钉夹住D6×2.5径向磁铁。板托挡环限制磁铁座轴向退出。磁铁侧壁和六角间隙用极少量可剥离中性胶止转消隙，固化后检查往返零位。</p><p>PCB由外缘托面、0.2 mm软绝缘片、后盖和M2双螺母保持。RP/RU/RF装在新增板托固定座；HS/HE/WF分体夹住原叉耳，后托挡肩捕获轴向位置，PET衬条消隙。板托不进入原摩擦预紧力链。</p><p>磁铁面至芯片封装表面名义2.0 mm，偏心目标0、实测≤0.3 mm。位于MT推荐间隙上限，实物必须核对0.5～2.0 mm间隙和磁场状态。任何AX4摩擦调整都须先拆测角附件，重装后重新标零并复核标定。</p>
<h2>腕部两轴各自测量</h2><div class="grid"><div><img src="images/wrist.png" alt="WF和WD实际安装结构"><p class="caption">金色：新增打印附件。绿色板：传感器。可在三维页单独检查双轴腕。</p></div><div><h3>WF屈伸</h3><p>MT板固定在前臂叉，磁铁参考固定在腕中心。转动WD不改变这对元件的相对关系。</p><h3>WD侧摆</h3><p>S1板固定在P012一体支架，磁铁固定在P010手掌盲座。D7平垫＋M2锁母机械防脱，0.5 mm打印补高片适配O22磁铁。两者随WF一起运动，所以读取的是WD。</p><p>原腕尺寸不适合再并排放一套同轴板；WD用实际偏置磁场的一维XYZ查表。必须用这只手臂测得曲线，腕屈伸×侧摆3×3交叉检验通过才输出可信角度。</p></div></div>
<h2>角度链继承</h2><pre>肩：R(-Y, RP) · R(X, HS) · R(-Z, RU)
肘/前臂：R(-Y, HE) · R(-Z, RF − 90°)
腕：Ry(WF) · Rx(WD)
A字：HS=45°，其余可调角=0°</pre><p>−90°固定钟向只计一次。{link('electronics/pose_bridge.py','pose_bridge.py')}输出R4坐标系的局部/世界矩阵与UE目标骨名；沿用项目既有UE参考姿势转换，不把原始角直接当成UE欧拉角。没有声称已完成UE硬件联机。</p>
<h2>依据</h2><p>MT选型和校验限制依据<a href="https://www.magntek.com.cn/upload/pdf/202407/MT6701_Rev.1.8.pdf">MagnTek官方数据手册</a>；WD的XYZ读数、CRC和转换状态依据<a href="https://www.ti.com/lit/ds/symlink/tmag5170.pdf">TI官方数据手册</a>。{link('verification/magnetic_model.json','磁场模型')}只作布局评估，未计钢件磁路和实际磁铁等级，不替代实测。</p>''')
    wd=next(r for r in pins if r['id']=='WD')
    page('WIRING.html','七路接线与活动走线',f'''<h2>六路O22 MT</h2><p>进入B组，保留原五线：1 GND黑、2 SENSOR_3V45红、3 CLK蓝、4 DO绿、5 CSN黄。B04/B08空置。</p>{table(['通道','载板位置','raw索引'],[[r['id'],r['connector']+' / '+r.get('carrier_reference',''),r['raw_index']] for r in pins if r['id']!='WD'])}
<h2>WD专用六线转接</h2>{table(['S1引脚','接到哪里'],wd['pins'].items())}<div class="box"><b>A01/J10是R5专用WD转接。</b>第5脚作为SDI，真正的CS_N单独接GPIO3，10 kΩ上拉到MCU 3V3。贴上“R5 WD / A01＋D2”标签，不能按普通O22五线板插法连接。</div><p>GPIO7输出时钟，GPIO43在WD事务期间作SDI，GPIO8读A组、GPIO9读B组。GPIO1保持使能，不能兼作WD片选；GPIO44/8是缓冲器驱动的输入，不能改成输出。WD事务后恢复SSI片选高并等待20 µs。</p><ol><li>断电测通断/短路；板电源用O22 3V45轨，片选上拉用MCU 3V3。</li><li>台面焊接并绝缘线尾，焊料和胶不超出板缘线尾包络。只持板边。</li><li>MT后盖两孔穿软绑线，WD绑一体支架横撑，焊盘不承拉力。</li><li>先留长、从关节外侧整理服务环，实物全范围检查后只修剪控制板端余量。</li></ol>
<h2>初次预留长度</h2>{table(['通道','芯数','每束预留','接头','经过运动轴'],[[r['channel'],r['conductor_count'],str(r['estimated_pre_cut_length_mm'])+' mm',r['controller_port'],' → '.join(r['crossed_axes'])] for r in routing['rows']])}<p>含120 mm控制板端尾量，是保守下料余量，不要求全部塞进骨杆。32 AWG多股柔线、单芯外径≤0.65 mm；关节处保持小束，不用硬排线或绷紧扎带。</p>
<h2>服务环</h2>{table(['轴','松弛段','最大采样锚距','长度余量'],[[r['axis'],str(r['service_length_mm'])+' mm',f"{r['maximum_sampled_anchor_separation_mm']:.1f} mm",f"{r['remaining_length_mm']:.1f} mm"] for r in routing['service_loops']])}<p>名义弯曲半径15 mm；两端系在关节两侧各自固定的打印件。三维线是中心线参考，锚点行程计算余量≥30 mm；没有完成柔线接触或应力仿真。</p><p><b>无电线跨WD侧摆轴。</b>WD板在腕中心，线跨WF；WF板在前臂，其线不跨WF。线环不能进入FW4/A8、肩钉头、W6L捕获槽或磁铁间隙。</p><p>断电全范围慢转：不拉直、不夹扁、不碰磁铁、不带动板夹。通电至少分两次累计记录60秒，轻摆线束不应出现CRC或场强故障；长线波形和抗干扰待实测，出现故障保留原始帧排查。{link('harness/routing_plan.json','锚点和长度')} · {link('electronics/pinmap.json','完整引脚')}</p>''')
    page('ASSEMBLY.html','完整装配与升级顺序',f'''<p>{link('assembly_guide/index.html',str(count)+'步交互动画')} · {link('assembly_guide/STEP_CARDS.html','全部步骤文字卡')}。动画使用最终生产分件；散件先有支承，才进入窄区。</p><ol><li><b>拆旧前记录R4手感和A8方向。</b>136件五金按轴分袋，M3压盖普通螺母与NL3预紧锁母分清。</li><li><b>WD先在台面预装。</b>独立板托装锁母、S1和绝缘片，再合P012支架；P010装补高片、磁铁、D7压片。在合腕叉前，外露面均可操作。</li><li><b>继承RP/RU/RF机械预装。</b>J001承托垫片/碟簧，J002定位，再合固定座、W6L和压盖；新加厚已避让原工具及肩钉路径。</li><li><b>RP测角必须先于肩外展叉。</b>后装外展叉会挡住侧向入口，动画已将这章提前。</li><li><b>磁铁和PCB托在台面预装。</b>M1.6螺纹少量低强度金属防松剂、固化后作见证标记。M2内螺母用J004＋微量中性胶暂留，固化再抽工具和装板；外螺母起牙后用薄壁套筒对顶。</li><li><b>RP/RU/RF：</b>板托先送至高2.0 mm位置，由外部手指保持。J003从下方送磁铁组件，落下1.45 mm进入六角；板托落到止口，挡环捕获后退出托叉，最后M2×8和平垫锁固。六角用极少可剥离中性胶消隙，不粘活动面。</li><li><b>HS/HE/WF：</b>外露肩钉先装磁铁，主体板托轴向进入，另一半夹壳先绕外侧再径向合拢；PET衬条避开摩擦面，M2×20双螺母固定，不改变AX4预紧。</li><li><b>走线、保持力复核、再校准。</b>若附件重量使摩擦需调整，先拆测角附件、调AX4，再重标定。</li></ol>
<h2>散件保持方式</h2>{table(['散件','保持方式'],[['垫片/碟簧','J001底托＋J002导向，或在外部先穿上螺钉杆。'],['磁铁侧送','J003底托＋重力，长柄外握；挡环就位才退出。'],['深处M2螺母','J004浅六角口＋薄纸；内螺母胶点固化保持，外螺母先起牙。'],['锁母侧入口','入口外露，指尖或低粘胶带暂留，螺钉起牙后去掉胶带。'],['PCB/绝缘片','开口朝上台面预装，手指压板边，保持后再合后盖。']])}<p>台面重新摆放、翻转和螺纹旋转用文字说明；动画不是成功实装录像。半剖和蓝色到位轮廓仅供观察；J001～J004是真实临时工具，不留在关节中。</p>''')
    manifest=load(OUT/'electronics/measurement_manifest_TEMPLATE.json')
    page('CALIBRATION.html','通电、标定与角度验收',f'''<div class="box pending">本包没有真实传感器采集数据。空白模板不能输出可信姿态；实测及独立验证全部通过后，calibrate.py才生成可用标定。</div><p>{link('electronics/firmware_source/build.ps1','固件源码/构建')} · {link('electronics/firmware_release/manifest.json','已编译固件哈希')} · {link('electronics/arm_reader.py','采集器')} · {link('electronics/calibrate.py','标定器')} · {link('electronics/pose_bridge.py','姿态导出')} · {link('electronics/measurement_manifest_TEMPLATE.json','测量模板')}</p><p>固件仅面向R5专用接线/O22载板/XIAO ESP32S3；烧录方法见firmware_release/FLASH_README.txt，必须指定实际COM口。本次没有连接或烧录硬件。主机依赖：<code>python -m pip install numpy pyserial</code>。</p>
<h2>标定前</h2><ol><li>原摩擦、防脱锁固完成，磁铁及六角填隙胶固化。六路MT实际封装表面间隙在0.5～2.0 mm内、偏心≤0.3 mm；先消除擦碰和晃动。</li><li>所有黄铜/原R4钢件和线束装齐再标定。MT场强状态正常，WD用±100 mT档，任何分量接近95 mT限制、CRC或状态异常均拒绝输出。</li><li>轻拉磁铁盖/板托不能退出或转位；每轴往返20次后回零漂移≤1°。超差先修复夹持/六角回差，不反复标零掩盖。</li><li>附件和走线装齐后复核代表姿态保持力。需调AX4时先拆测角附件，最终机械调整后完整重标。</li></ol>
<h2>实际采集</h2><p>用可靠机械角度尺在每个关节两侧建立参考。上臂/前臂旋转按自身轴和零位测量，不用手掌倾角冒充。记录参考工具、夹持和读数；A字HS=45°，其余可调角0°，RF固定−90°不重复加入。</p><p>复制模板为measurements.json，按{len(manifest['measurements'])}条记录分别采集，每条独立文件、≥25个有效帧。普通标定固定其余轴；cross_joint/coupled改变其他轴，同时独立测量被检轴参考角。</p><pre>python arm_reader.py --port COM实际编号 --seconds 2 --output captures/RP_calibration_01.json
python calibrate.py --manifest measurements.json --output measured_calibration.json
python arm_reader.py --port COM实际编号 --seconds 10 --calibration measured_calibration.json --output accepted_capture.json
python pose_bridge.py --capture accepted_capture.json --calibration measured_calibration.json --output arm_pose.json</pre><p>从electronics目录执行，先创建captures文件夹；替换实际COM编号，不自动探测端口。R5AR v1协议280字节，名义50 Hz扫描，单次≤55秒，结束发送STOP。</p>
<h2>验收门槛</h2>{table(['检查','要求'],[['分轴标定','每轴≥11站，覆盖全程；WD间隔≤5°，用实测XYZ矢量曲线。'],['正向/反向独立验证','各≥5站，最大误差≤2°、RMS≤1°，每站静态峰峰≤1°。'],['相邻关节干扰','六路MT各≥3组不同关节组合；被检轴参考角由机械尺读出。'],['腕交叉','WF=−65/0/70° × WD=−20/0/30°共9站。只转一轴时另一路稳定。'],['WD曲线','静态分量标准差≤0.1 mT，局部灵敏度≥0.15 mT/°；残差合格且无多解。'],['数据','SSI CRC6/状态、TMAG CRC4/转换计数/错误位/配置、USB CRC32/会话/序号全检查；故障停止，不沿用旧角。']])}<p>这些是工程验收目标，不是已经测得的精度。打印误差、钢件磁化、磁铁强度、长线波形和蠕变需要实际确认。独立验证失败时程序拒绝合格标定，保留原始文件排查。</p>''')
    cards=''.join(f'<section class="card"><p class="eyebrow">{s["number"]} / {count} · {esc(s["chapter"])}</p><h2>{esc(s["title"])}</h2><p>{esc(s["note"])}</p><p><b>零件：</b>{esc("、".join(s["parts"]))}</p><p><b>支承：</b>{esc(s.get("support","外部支承"))}</p><p>{link("index.html?step="+str(s["number"]),"打开本步动画")}</p></section>' for s in steps)
